const queue = ["Saved", "Synced", "Shared"];
let delay = 0;
let toast = queue.shift();

while (toast) {
  setTimeout(() => console.log(toast), delay);
  delay += 300;
  toast = queue.shift();
}
// after 0, 300 and 600 ms: undefined, undefined, undefined

const queue = ["Saved", "Synced", "Shared"];
let delay = 0;

while (queue.length > 0) {
  const toast = queue.shift(); // a new variable on every pass
  setTimeout(() => console.log(toast), delay);
  delay += 300;
}
// after 0, 300 and 600 ms: Saved, Synced, Shared
